/*! `gdscript` grammar for Highlight.js — hand-written for LibDoc */
hljs.registerLanguage("gdscript", function (hljs) {
  var IDENT_RE = hljs.UNDERSCORE_IDENT_RE;

  var KEYWORDS =
    "if elif else for while match when break continue pass return await yield " +
    "assert class class_name extends in as is not and or void static namespace " +
    "trait signal enum set breakpoint preload var const true false null";

  var BUILT_IN =
    "bool int float String StringName NodePath Vector2 Vector2i Vector3 Vector3i " +
    "Vector4 Vector4i Rect2 Rect2i Transform2D Transform3D Plane Quaternion AABB " +
    "Basis Projection Color RID Object Callable Signal Dictionary Array " +
    "PackedByteArray PackedInt32Array PackedInt64Array PackedFloat32Array " +
    "PackedFloat64Array PackedStringArray PackedVector2Array PackedVector3Array " +
    "PackedVector4Array PackedColorArray Node Node2D Node3D CanvasItem Control " +
    "Label CanvasLayer CharacterBody2D Area2D StaticBody2D RigidBody2D " +
    "AnimatableBody2D CollisionShape2D TileMapLayer RefCounted Resource";

  var IDENT = { variants: [{ begin: IDENT_RE }] };

  var comment = hljs.COMMENT("#", "$");

  var docComment = hljs.inherit(comment, {
    className: "doctag",
    begin: /##[ \t]@\w+/,
  });

  var strings = {
    className: "string",
    variants: [
      { begin: /[rR]?"""/, end: /"""/, contains: [hljs.BACKSLASH_ESCAPE] },
      { begin: /[rR]?'''/, end: /'''/, contains: [hljs.BACKSLASH_ESCAPE] },
      { begin: /\^"/, end: /"/, contains: [hljs.BACKSLASH_ESCAPE], relevance: 5 },
      { begin: /&"/, end: /"/, contains: [hljs.BACKSLASH_ESCAPE], relevance: 5 },
      { begin: /"/, end: /"/, contains: [hljs.BACKSLASH_ESCAPE] },
      { begin: /'/, end: /'/ },
    ],
  };

  var annotations = {
    className: "meta",
    begin: /@(?:export|export_[a-z_]+|onready|tool|icon|abstract)\b/,
  };

  var nodePath = {
    className: "built_in",
    begin: /\$[A-Za-z][A-Za-z0-9_]*(?:\/[A-Za-z0-9_]+)*/,
  };

  var uniqueName = { className: "built_in", begin: /%[A-Za-z][A-Za-z0-9_]*/ };

  var numbers = {
    className: "number",
    variants: [
      { begin: /\b0[xX][0-9a-fA-F_]+/ },
      { begin: /\b0[bB][01_]+/ },
      { begin: /\b\d[\d_]*\.[\d_]*([eE][+-]?[\d_]+)?\.[\d_]*/ },
      { begin: /\b\d[\d_]*\.[\d_]*([eE][+-]?[\d_]+)?/ },
      { begin: /\b\d[\d_]*/ },
    ],
  };

  var classNameDecl = {
    beginKeywords: "class_name",
    end: /[ \t\n=]/,
    contains: [IDENT],
    keywords: { className: [IDENT_RE] },
  };

  var funcDecl = {
    className: "function",
    beginKeywords: "func",
    end: /[ \t\n(]/,
    contains: [IDENT],
    keywords: { className: [IDENT_RE] },
  };

  var selfKeywords = {
    className: "variable.language",
    beginKeywords: "self super",
    end: /[ \t\n.,;:)\]}]/,
  };

  var params = {
    className: "params",
    variants: [
      {
        begin: /\(/,
        end: /\)/,
        excludeBegin: true,
        excludeEnd: true,
        contains: ["self", strings, numbers, nodePath, uniqueName],
        keywords: { className: [IDENT_RE] },
      },
    ],
  };

  var gdpragmas = {
    className: "meta",
    begin: /^#[ \t]*(?:if|endif|region|endregion|else|elif|end|match|when|warning_ignore|class)\b/,
    relevance: 10,
  };

  var textblocks = {
    className: "meta",
    begin: /\{\{\|?|\|\}\}/,
    relevance: 10,
  };

  return {
    name: "GDScript",
    case_insensitive: false,
    keywords: {
      keyword: KEYWORDS,
      built_in: BUILT_IN,
      literal: "PI TAU INF NAN",
    },
    contains: [
      docComment,
      gdpragmas,
      comment,
      annotations,
      classNameDecl,
      funcDecl,
      selfKeywords,
      nodePath,
      uniqueName,
      strings,
      textblocks,
      numbers,
      params,
    ],
  };
});
